export function solve(puzzle: string): Record<string, number> | undefined {
  // 1. Parse the puzzle string into words and the operator
  // Expected format: "WORD1 + WORD2 == RESULT" or "WORD1 + WORD2 + WORD3 == RESULT"
  const parts = puzzle.trim().split(/\s+/);
  if (parts.length < 3) return undefined;

  // Find the operator (== or +)
  let opIndex = -1;
  let op = "";
  for (let i = 0; i < parts.length; i++) {
    if (parts[i] === "==" || parts[i] === "+") {
      opIndex = i;
      op = parts[i];
      break;
    }
  }

  if (opIndex === -1) return undefined;

  const leftWords = parts.slice(0, opIndex).filter(w => w.length > 0);
  const rightWord = parts[opIndex + 1].trim();

  if (leftWords.length === 0 || rightWord.length === 0) return undefined;

  // 2. Extract all unique letters
  const letters = new Set<string>();
  const words = [rightWord, ...leftWords]; // Order doesn't strictly matter for set, but good for debugging

  for (const word of words) {
    for (const char of word) {
      if (char.match(/[a-zA-Z]/)) {
        letters.add(char.toLowerCase());
      }
    }
  }

  const letterArray = Array.from(letters);
  if (letterArray.length > 10) return undefined; // Pigeonhole principle

  // 3. Identify leading letters (cannot be 0)
  const leadingLetters = new Set<string>();
  for (const word of words) {
    const firstChar = word[0];
    if (firstChar && firstChar.match(/[a-zA-Z]/)) {
      leadingLetters.add(firstChar.toLowerCase());
    }
  }

  // 4. Prepare constraints
  // We need to map each letter to a digit 0-9
  // We will use backtracking to assign digits

  const letterMap = new Map<string, number>();
  const usedDigits = new Set<number>();

  // Helper to check if a word is valid with current mapping
  const isValidWord = (word: string): boolean => {
    if (word.length === 0) return true;
    const firstChar = word[0];
    if (leadingLetters.has(firstChar.toLowerCase())) {
      if (letterMap.get(firstChar.toLowerCase()) === 0) return false;
    }
    return true;
  };

  // Helper to convert word to number
  const wordToNumber = (word: string): number => {
    let num = 0;
    for (const char of word) {
      const digit = letterMap.get(char.toLowerCase());
      if (digit === undefined) return -1; // Should not happen if we only call with assigned letters
      num = num * 10 + digit;
    }
    return num;
  };

  // Backtracking function
  const backtrack = (index: number): boolean => {
    if (index === letterArray.length) {
      // All letters assigned, check the equation
      const resultNum = wordToNumber(rightWord);
      let leftSum = 0;
      for (const word of leftWords) {
        leftSum += wordToNumber(word);
      }
      return leftSum === resultNum;
    }

    const letter = letterArray[index];
    const isLeading = leadingLetters.has(letter);

    for (let digit = 0; digit <= 9; digit++) {
      if (usedDigits.has(digit)) continue;
      if (isLeading && digit === 0) continue;

      letterMap.set(letter, digit);
      usedDigits.add(digit);

      // Optional: Pruning check? 
      // For small alphametics, full check at leaf is usually fast enough.
      // However, we can check if any word becomes invalid due to leading zero immediately.
      // But since we check leading zero before assignment, words are structurally valid.
      // We could check if the sum is already too big/small, but that's complex with variable number of terms.
      // Let's stick to leaf check for simplicity and correctness.

      if (backtrack(index + 1)) return true;

      // Backtrack
      usedDigits.delete(digit);
      letterMap.delete(letter);
    }

    return false;
  };

  if (backtrack(0)) {
    return Object.fromEntries(letterMap);
  }

  return undefined;
}
